  Activity_126366_ActivityPlot = {
    Text = "기억의 한 장면은 먼지투성이로 보관되고, 여정의 한 단락은 과거 속에 새겨진다. 추억에 빠질 때에는 경의의 예물을 바치는 것을 잊지 말자."
