  Activity_126492_ActivityTips = {
    Text = "<Title: 고국잡조>\n·이번 한정 기행에는 8개의 선물 패키지가 포함되어 있으며, 첫 번째 패키지는 무료로 수령할 수 있고, 2-8번째 패키지는 「고국잡조」를 구매한 후 수령할 수 있습니다.\n·「고국잡조」를 구매하면 즉시 2번째 패키지 보상을 수령할 수 있으며, 이후 패키지는 일정 시간이 경과한 후 수령할 수 있습니다.\n·1월 26일 9:00 전에 「고국잡조」를 구매하면 추가 보상을 획득할 수 있습니다: 전용 아이콘 「부채 속 진형」, 「형체 없는 자의 초대장」×10! 1월 26일 9:00 이후 구매 시 한정 전용 보상을 더 이상 획득할 수 없습니다. \n· 구매 후, 이번 한정 기행의 지속 기간이 영구로 변경되며, 모든 패키지를 수령한 다음 날 이벤트가 종료됩니다.\n·「고국잡조」는 구매 기간이 제한되어 있으며, 기간이 지나면 더 이상 구매할 수 없습니다. 비밀수호자께서는 2월 23일 9:00 전에 적절히 구매해 주시기 바랍니다."
  },
  Activity_126492_BannerText = {
    Text = "기간 한정 특별 기행!"
