  Activity_148889_ActivityName = {
    Text = "본원 오지에"
  },
  Activity_148889_ActivityTips = {
    Text = "<Title:이벤트 규칙>\n·「본원 오지르」 이벤트 기간 동안, 비밀수호자는 본원 오지르가 포함된 시스템 프리셋 파티로 지정 스테이지를 무제한 체험할 수 있습니다.\n·이벤트 스테이지 체험 시, 편성 내 깨어남체를 조정할 수 없습니다.\n<Title:이벤트 보상>\n·최초로 스테이지 도전을 달성한 후, 이벤트 화면에서 체험 보상을 수령할 수 있습니다."
  },
  Activity_15788_ActivityName = {
    Text = "연금 미학"
  },
  Activity_15788_ActivityTips = {
    Text = "이벤트 규칙:\n1,「연금 미학」 이벤트 기간 동안, 비밀수호자가 「금권 수색」을 클리어하면 일부 소재 보상이 2배가 되며, 매일 3회까지 적용됩니다.\n2,당일 미사용 2배 보상 횟수는 익일 9시(GMT+8)에 초기화되오니, 비밀수호자께서는 잊지 말고 사용해 주세요～"
