  Activity_15793_ActivityName = {
    Text = "비 내리는 마을의 유령"
  },
  Activity_15793_ActivityPlot = {
    Text = "비가 내리는 밤마다, 실타래의와 적막이 함께합니다.\n누군가는 사랑을 잃고, 누군가는 존엄을 잃습니다.\n또 누군가는 자신의 머리를 잃습니다."
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:참여 조건>\n·「조사 작전 행동」2-9·일반 완료 후 참여 가능합니다.\n<Title:조사 작전 이벤트>\n·이벤트 기간 동안 매일 「우진유영」의 새로운 조사 작전 이벤트가 공개되며, 수비인은 물자를 소모하지 않고 해금하여 조사 작전를 진행할 수 있습니다. 조사 작전 이벤트를 완료하면 무구의 코어, 조사 작전 휘장 및 수비인 경험치 등 조사 작전 보상을 획득할 수 있습니다.\n·이벤트 종료 후, 「우진유영」의 조사 작전 진행도는 유지되며, 수비인은 특수 파견 기록에서 융식의 구슬을 소모하여 미개방 조사 작전를 해금할 수 있습니다. 이벤트 기간 중 미완료된 조사 작전 이벤트를 완료하면 이벤트 기간과 동일한 조사 작전 보상을 획득할 수 있습니다.<Title:한정 보상>\n·이벤트 기간 동안 한정 보상이 공개되며, 수비인이 「우진유영」 일반 모드를 클리어하고 「우진유영」의 조사 작전 이벤트를 완료하면 무구의 코어, 현자의 돌 및 은빛 코어 보상을 획득할 수 있습니다! 한정 보상은 이벤트 기간에만 개방되며, 이벤트 종료 후에는 완료 및 수령이 불가합니다."
  },
  Activity_15793_UnlockConditionExplanation = {
    Text = "「조사 작전 행동」 2-9·일반 클리어 후 해금"
