  Activity_21502_ActivityTips = {
    Text = "<Title:이벤트 규칙>\n·「바다의 사도」 이벤트 기간 동안, 비밀 수호자는 미리암이 포함된 시스템 프리셋 팀으로 지정 스테이지를 무제한 체험할 수 있습니다.\n·이벤트 스테이지 체험 시, 편성 내 깨어남체를 조정할 수 없습니다.\n<Title:이벤트 보상>\n·최초로 스테이지 도전을 달성하면, 이벤트 화면에서 체험 보상을 수령할 수 있습니다."
  },
  Activity_21781_ActivityName = {
    Text = "자유 연구"
  },
  Activity_21781_ActivityPlot = {
    Text = "미션 완료 시 「영역 탐구」에서 특정 깨어남체 또는 「윤회의 상」에서 특정 명륜을 자유롭게 선택하실타래 수 있습니다!"
  },
  Activity_21781_ActivityTips = {
    Text = "이벤트 규칙:\n1. 누적 깨어남 50회, 누적 로그인 3일, 7일 달성 시 「원질의 낙원」 보상을 획득하실타래 수 있습니다. 「원질의 낙원」은 「물자 → 소모품」에서 사용 가능하며, 사용 후 「영역 탐구」에서 특정 깨어남체 1개를 자유 선택하여 깨어남하실타래 수 있습니다.\n2. 누적 깨어남 300회, 1000회 그리고 누적 로그인 30일 달성 시 「회전의 책」 보상을 획득하실타래 수 있습니다. 「회전의 책」은 「물자 → 소모품」에서 사용 가능하며, 사용 후 「윤회의 상」에서 특정 명륜 1개를 자유 선택하여 획득하실타래 수 있습니다."
  },
  Activity_22367_ActivityName = {
    Text = "영지 폭발"
  },
  Activity_22367_ActivityTips = {
    Text = "이벤트 규칙:\n1,「영지 폭발」 이벤트 기간 동안, 비밀 수호자가 「제제 담금질」에서 조사 또는 재현 시, 추가 50%의 보상을 획득합니다(비밀 수호자 경험치치 제외). 매일 횟수 제한 없음."
  },
  Activity_23671_ActivityName = {
    Text = "심해 잠수 대국"
  },
  Activity_23671_ActivityPlot = {
    Text = "이벤트 기간 동안, 비밀 수호자가 「환몽 심해 잠수」와 「위상 대국」을 통해 획득하는 비밀 수호자 경험치치가 2배로 지급되며, 일일 상한이 480포인트로 상향됩니다."
  },
  Activity_23671_ActivityTips = {
    Text = "이벤트 규칙:\n1,「심해 잠수 대국」 이벤트 기간 동안, 비밀 수호자가 「환몽 심해 잠수」와 「위상 대국」을 통해 획득하는 비밀 수호자 경험치치가 2배로 지급되며, 일일 상한이 480포인트로 상향됩니다. 핵심 과제를 동시에 해금한 경우, 해당 경로로 획득하는 비밀 수호자 경험치치가 2배의 2배로 지급되며, 일일 상한은 480포인트로 유지됩니다.\n2,당일 사용하지 않은 2배 비밀 수호자 경험치치는 다음 날 9시(GMT+8)에 초기화되오니, 비밀 수호자께서는 잊지 말고 소진해 주세요～"
  },
  Activity_23693_ActivityName = {
    Text = "창백한 후예"
  },
  Activity_23693_ActivityPlot = {
    Text = "전해지는 바에 따르면, 론디니엔의 지하에는 유일한 문이 하나 있다고 합니다.\n그 문은 창백한 군주가 있는 곳으로 통합니다…"
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:참여 조건>\n·의식 잠수 「기사의 소원」 일반 모드를 클리어한 후 참여할 수 있습니다. \n<Title:조사 이벤트>\n·활동 기간 동안, 매일 「창백한 후예」의 새로운 조사 이벤트가 공개되며, 비밀지기는 물자를 소모하지 않고 조사를 해금하여 진행할 수 있습니다. 조사 이벤트를 완료하면 무구의 코어, 조사 휘장, 비밀지기 경험치 등의 조사 보상을 획득할 수 있습니다.\n·활동 종료 후, 「창백한 후예」의 조사 진행도는 보존되며, 비밀지기는 의식 잠수에서 융식의 구슬을 소모하여 미개방 조사를 해금할 수 있습니다. 활동 기간 중 미완료된 조사 이벤트를 완료하면 활동 기간과 동일한 조사 보상을 획득할 수 있습니다.<Title:한정 보상>\n·활동 기간 동안 한정 보상이 공개되며, 비밀지기가 「창백한 후예」 일반 모드를 클리어하고 「창백한 후예」의 조사 이벤트를 완료하면, 칠흑의 잠금쇠와 은빛 코어 보상을 획득할 수 있습니다! 한정 보상은 활동 기간에만 개방되며, 활동 종료 후에는 완료 및 수령이 불가합니다."
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "의식 잠수 「기사의 소원」 클리어 후 해금"
  },
  Activity_23723_ActivityName = {
    Text = "폭풍 전야"
  },
  Activity_23723_ActivityTips = {
    Text = "이벤트 규칙:\n1,이벤트 기간 동안, 조사 작전 행동 제5장이 임시 폐쇄되며, 열쇠령 「영원한 집념」은 일시적으로 조사 작전 행동 제4장 클리어 시 획득할 수 있습니다.\n2,이벤트 종료 후, 조사 작전 행동 제5장이 다시 개방되며, 열쇠령 「영원한 집념」은 여전히 조사 작전 행동 제5장 클리어가 필요합니다.\n3,또한, 이전에 달성한 제5장 업적 보상, 스테이지 업적 보상, 탐색 보상, 클리어 보상은 모두 유지되며, 재개방 시(현재 계획은 12월 27일), 관련 완료 진행도는 가능한 한 그대로 유지되므로 중복 완료할 필요가 없습니다."
  },
  Activity_23870_ActivityName = {
    Text = "위상 추연"
  },
  Activity_23870_ActivityTips = {
    Text = "이벤트 규칙:\n1,이벤트 기간 동안, 이벤트 임무를 완료하면 보상을 획득할 수 있습니다.\n2,이벤트 종료 후, 수령하지 않은 이벤트 보상은 더 이상 수령할 수 없으니, 비밀 수호자께서는 잊지 말고 제때 수령해 주세요～"
  },
