  },
  Activity_44273_ActivityPlot = {
    Text = "그는 너희를 위해 고생하며, 너희의 재앙을 짊어졌다. \n그가 흘린 혈육으로, 너희는 치유받았고, \n그가 바친 생명으로, 너희는 용서받았다."
