    Text = "거인의 몰락"
  },
  Activity_45664_ActivityPlot = {
    Text = "끝없는 바다, 작열하는 태양, 유배된 블레셋의 영웅과 그의 유일한 수행원.\n이것은 「찾음」에 관한 이야기입니다."
