  },
  Activity_48826_ActivityPlot = {
    Text = "매일 로그인하면 기념 한정 SSR 운명의 바퀴 「극야와 여명」을 수령할 수 있으며, 총 16개를 수령할 수 있습니다!"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:소개>\n이것은 플레이어에게 바치는 시입니다. 이상에 대해, 신념에 대해, 함께 걸어온 시간에 대해. 진심 어린 마음이 영원히 뛰기를, 은열쇠가 앞길을 인도하기를 바랍니다.\n\n<Title:이벤트 규칙>\n·이벤트 기간 동안, 비밀지기는 매일 로그인 후 「극야와 여명」에서 기념 한정 SSR 운명의 바퀴 「극야와 여명」을 수령할 수 있으며, 총 16회 수령할 수 있습니다.\n·보상은 비밀지기의 누적 로그인에 따라 순차적으로 해금되며, 당일 로그인 보상은 9시(GMT+8)에 갱신됩니다."
  },
  Activity_48826_BannerText = {
    Text = "무료 한정 SSR 명륜 획득"
  },
  Activity_48827_ActivityName = {
    Text = "모자 속 은심"
  },
  Activity_48827_ActivityPlot = {
    Text = "불완전한 통계에 따르면, 지난 반년 동안 학교 고양이의 모자는 학생들에게 수천 번이나 두드려졌으며, 많은 작고 눈에 띄지 않는 은심이 바닥에 떨어졌지만 아무도 관심을 두지 않았습니다. 청소를 담당하는 교직원이 매우 곤란해하여, 현재 학교에서 이 은심들을 수거하여 완전히 세척한 후 분실타래물 보관소에 보관하고 있으니, 분실타래자께서는 직접 방문하여 적시에 수령해 주시기 바랍니다."
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:소개>\n불완전한 통계에 따르면, 지난 반년 동안 학교 고양이의 모자는 학생들에게 수천 번이나 두드려졌으며, 많은 작고 눈에 띄지 않는 은심이 바닥에 떨어졌지만 아무도 관심을 두지 않았습니다. 청소를 담당하는 교직원이 매우 곤란해하여, 현재 학교에서 이 은심들을 수거하여 완전히 세척한 후 분실타래물 보관소에 보관하고 있으니, 분실타래자께서는 직접 방문하여 수령해 주시기 바랍니다.\n\n<Title:이벤트 규칙>\n·이벤트 기간 동안, 비밀지기는 매일 로그인 후 「모자 속의 은심」에서 「은심」×1000을 수령할 수 있으며, 최대 5회까지 수령할 수 있습니다.\n·보상은 비밀지기의 누적 로그인에 따라 순차적으로 해금되며, 당일 로그인 보상은 9시(GMT+8)에 갱신됩니다."
