  Activity_61156_ActivityName = {
    Text = "종언 기행"
  },
  Activity_61156_ActivityTips = {
    Text = "이벤트 규칙:\n1. 수호자 님께서 지정된 기행 미션 완료 시 「종언 기행」에서 보상을 수령하실타래 수 있습니다.\n2. 「종언 기행」은 영구 개방 이벤트입니다.\n3. 「고급 기행」을 해제하면 미션 완료 시 추가 보상을 수령하실타래 수 있습니다.\n4. 주의 사항: 본 이벤트에서 해제한 「고급 기행」은 본 이벤트에서만 유효합니다. 수호자 님께서는 합리적으로 소비해 주시기 바랍니다."
  },
  Activity_61369_ActivityName = {
    Text = "점진 율려"
  },
  Activity_61369_ActivityPlot = {
    Text = "비밀지기는 다음 한정 운명의 바퀴 중 하나를 선택하여 깨어남할 수 있습니다!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:소개>\n흑지에 파란이 일고, 운명의 바퀴가 끊임없이 순환하는 가운데, 하멜린의 선율에 이끌려 무한한 율려가 합주하여 당신이 걸어온 여정의 운명의 바퀴를 이룹니다. 그것들의 힘이 종말 소나타의 쉼표까지 당신과 함께하기를 바랍니다.\n\n<Title:이벤트 규칙>\n·이벤트 기간 동안 단 하루만 로그인하면, 다음 12개의 한정 운명의 바퀴 중 하나를 선택하여 깨어남할 수 있습니다: 「신왕의 송가」, 「가장 소중한 소장품」, 「장미의 이름으로」, 「고통을 넘어」, 「은밀한 탄생」, 「여왕의 계율」, 「신언 석판」, 「기체 역식」, 「경건한 위력」, 「시전의 구미」, 「자비로운 양육」, 「행운의 시간」."
  },
  Activity_61369_BannerText = {
    Text = "무료 한정 명륜 획득"
  },
  Activity_61370_ActivityName = {
    Text = "순은의 초심"
  },
  Activity_61370_ActivityPlot = {
    Text = "매일 로그인하면 기념 한정 SSR 운명의 바퀴 「순은의 마음」을 수령할 수 있으며, 총 16개를 수령할 수 있습니다!"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:소개>\n세계가 어떻게 뒤집히든, 모든 사람이 처음의 맑고 순수한 순은의 마음을 지키는 한, 이야기는 끝없이 순환하며, 새로운 생명이 황폐한 대지 위에 다시 태어날 것입니다.\n\n<Title:이벤트 규칙>\n·이벤트 기간 동안, 비밀지기는 매일 로그인 후 「순은의 초심」에서 기념 한정 SSR 운명의 바퀴 「순은의 초심」을 수령할 수 있으며, 총 16회 수령할 수 있습니다.\n·보상은 비밀지기의 누적 로그인에 따라 순차적으로 해금되며, 당일 로그인 보상은 9시(GMT+8)에 갱신됩니다."
  },
  Activity_61370_BannerText = {
    Text = "무료 한정 SSR 명륜 획득"
  },
  Activity_61371_ActivityName = {
    Text = "여섯 날개의 기도"
  },
  Activity_61371_ActivityPlot = {
    Text = "흑지의 동요 속에서, 무한 차원에서 온 은심이 차원의 틈새를 통해 흑지 주변에 흩어졌습니다. 타비는 그것들을 정성스럽게 모아 흑지 한쪽에 놓아두었습니다. 비록 이 은심들이 융식의 확산을 막을 수는 없지만, 그 안에 담긴 그리움과 마음은 영원히 찬란하게 빛날 것입니다."
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:소개>\n흑지의 동요 속에서, 무한 차원에서 온 은심이 차원의 틈새를 통해 흑지 주변에 흩어졌습니다. 타비는 그것들을 정성스럽게 모아 흑지 한쪽에 놓아두었습니다. 비록 이 은심들이 융식의 확산을 막을 수는 없지만, 그 안에 담긴 그리움과 마음은 영원히 찬란하게 빛날 것입니다.\n\n<Title:이벤트 규칙>\n·이벤트 기간 동안, 비밀지기는 매일 로그인 후 이벤트에서 「은심」× 1000을 수령할 수 있으며, 최대 6회까지 수령할 수 있습니다.\n·이벤트 기간 동안, 비밀지기가 누적 로그인 7일째에는 해당 기간 한정 깨어남체 「타비」를 직접 수령할 수 있습니다!\n·보상은 비밀지기의 누적 로그인에 따라 순차적으로 해금되며, 당일 로그인 보상은 9시(GMT+8)에 갱신됩니다."
  },
  Activity_61371_BannerText = {
    Text = "출석을 통해 은심 획득"
  },
