  Activity_66375_ActivityName = {
    Text = "결승: 원초의 그림자"
  },
  Activity_66375_ActivityPlot = {
    Text = "그의 시선이 만천 차원을 스쳐 지나가고, 그와 눈이 마주친 것은 만천의 은빛 형상들이었다.\n그들은 미약하고, 연약하다. 그들은 기억하기 위해 싸우며, 죽음에 이르러서야 멈춘다."
  },
  Activity_66375_ActivityStageEndContent = {
    Text = "이벤트가 달성되었습니다. 계속 조사를 진행할 수 있습니다."
  },
  Activity_66375_ActivityTips = {
    Text = "<Title: 공전 원초>\n·「공전 원초」에는 재현 불가능한 7개의 관문이 포함되어 있으며, 원초지시를 직접 도전합니다. 이벤트 첫날 앞 3개가 개방되고, 이후 3일마다 1개씩 개방됩니다.\n·매회 도전에서 해당 원초지시를 격파하면 해당 보상을 획득할 수 있습니다.\n·각 종류의 원초지시에는 대량의 분신이 있으며, 어떤 종류의 원초지시가 임의의 수비인에 의해 격파될 때마다 해당 유형 원초지시의 「세계 잔여 수량」이 1 감소합니다. 해당 유형 원초지시의 모든 분신이 소멸되면 해당 관문이 폐쇄되어 더 이상 도전할 수 없습니다.\n·모든 관문은 「융재흑조·종말」의 영향을 받지만, 각 관문마다 다른 「순은지심」 유물이 제공되어 강력한 버프를 부여합니다. 또한 각 관문에는 「전지지안」 유물이 제공되어, 타비가 전투 시작 시 광기 120을 획득하고, 타비의 모든 피해, 보호막, 생명력 회복 효과가 50% 증가합니다.\n·모든 관문에서 반드시 조력을 선택해야 하며, 전체 이벤트 기간 중 서로 팔로우한 수비인은 1회만 조력을 제공할 수 있습니다. 조력 사용으로 인해 실타래제 동조율 보상은 기본 보상에서 50% 추가 증가합니다.\n·수비인은 최소 조사 작전 행동 2-9를 완료해야 해당 이벤트에 참여할 수 있습니다.\n\n<Title:조사 작전 행동: 종장>\n·각 종류 원초지시의 본체는 여전히 조사 작전 행동 9-5부터 9-11에서 직접 격파해야 합니다. 이 특수 관문에는 업적, 별 수가 없으며, 「전지지안」 유물의 도움도, 조력 사용도 불가능하고, 난이도가 더 높습니다.\n·「공전 원초」 이벤트 종료 후 「조사 작전 행동: 종장」의 후속 관문이 해금됩니다. 다른 수비인과 함께 각 종류 원초지시의 모든 분신을 소멸시키면, 조사 작전 행동 9-5부터 9-11의 해당 관문을 조기 해금할 수 있습니다."
  },
  Activity_66375_BannerText = {
    Text = "기간 한정 이벤트!"
  },
  Activity_66908_ActivityName = {
    Text = "풍양의 숨결"
  },
  Activity_66908_ActivityTips = {
    Text = "<Title:이벤트 규칙>\n·「풍양의 숨결」 이벤트 기간 동안, 비밀 수호자는 타이이스가 포함된 시스템 프리셋 팀으로 지정 스테이지를 무제한 체험할 수 있습니다.\n·이벤트 스테이지 체험 시, 편성 내 깨어남체를 조정할 수 없습니다.\n<Title:이벤트 보상>\n·최초로 스테이지 도전을 달성하면, 이벤트 화면에서 체험 보상을 수령할 수 있습니다."
  },
  Activity_67077_ActivityName = {
    Text = "여정 회상 선물 Ⅸ"
  },
  Activity_67077_ActivityPlot = {
    Text = "기억의 한 장면은 먼지투성이로 보관되고, 여정의 한 단락은 과거 속에 새겨진다. 추억에 빠질 때에는 경의의 예물을 바치는 것을 잊지 말자."
  },
  Activity_67718_ActivityName = {
    Text = "봄이 시들기 전에·복각"
  },
  Activity_67718_ActivityPlot = {
    Text = "소녀들의 웃음소리가 울려 퍼지며, 아직 불길이 타오르지 않은 정원에 메아리칩니다.\n이 아름다운 과거를 위해 잠시 멈춰 서세요, 나의 친구여.\n아직 시들지 않은 봄이 나지막이 들려주는 지난날의 이야기를 들어보세요."
  },
  Activity_67718_ActivityStageEndContent = {
    Text = "이벤트가 종료되었습니다. 현재 「콜레트의 화방」만 참여할 수 있습니다."
