  Activity_89008_ActivityName = {
    Text = "차원을 넘는 추적"
  },
  Activity_89008_ActivityPlot = {
    Text = "그녀는 수많은 차원, 수많은 세계를 넘나들며 수많은 희망과 절망을 겪었지만, 결코 발걸음을 멈추지 않을 것입니다. 왜냐하면, 그녀는 자신의 목적지를 분명히 알고 있기 때문입니다—당신이 있는 곳."
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:소개>\n1,이벤트 기간 동안, 비밀지기는 매일 로그인 후 「되돌아오는 차원의 추종」에서 당일 출석 보상을 수령할 수 있습니다.\n2,보상은 비밀지기의 누적 로그인에 따라 순차적으로 해금되며, 당일 출석 보상은 9시(GMT+8)에 갱신됩니다.\n\n<Title:한정 임무>\n·이벤트 기간 동안, 누적 로그인 7일을 달성하면 한정 임무를 완료하여 「간이 환의 회형권(1기)」×1을 획득할 수 있습니다!\n·5월 26일 9:00 - 6월 9일 9:00(GMT+8) 기간 동안, 「상점:환의 주문」에서 「간이 환의 회형권(1기)」을 사용하여 기본 환의를 교환할 수 있습니다.\n·「간이 환의 회형권(1기)」의 추가 획득 방법은 커뮤니티와 공지에서 확인할 수 있습니다."
  },
  Activity_89008_BannerText = {
    Text = "출석을 통해 많은 무구의 은핵 획득"
  },
  Activity_89576_ActivityName = {
    Text = "희망이 다시 싹트기를"
  },
  Activity_89576_ActivityPlot = {
    Text = "매일 로그인 시 기념 한정 SSR 명륜 「폐허로부터의 부활」을 수령하실타래 수 있으며, 총 16개까지 수령하실타래 수 있습니다!"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:소개>\n세계가 붕괴하고 있다, 이런 세계에서 절망과 고통은 일상이다. 나는 익숙해져야만 한다. 하지만…… 여전히 따뜻함은 내 심장 속에서 조그맣게 뛰며, 가슴을 뚫고 나올 그 순간을 기다리고 있다.\n\n<Title:이벤트 규칙>\n· 이벤트 기간 동안, 수호자 님은 매일 로그인 후 「희망이 다시 싹트기를」에서 기념 한정 SSR 명륜 「폐허로부터의 부활」을 수령하실타래 수 있으며, 총 16회까지 수령하실타래 수 있습니다.\n· 보상은 수호자 님의 누적 로그인 일자에 따라 순차적으로 해제되며, 당일 로그인 보상은 10시(한국 시간 기준)에 갱신됩니다."
  },
  Activity_89576_BannerText = {
    Text = "무료 한정 SSR 명륜 획득"
  },
  Activity_89729_ActivityName = {
    Text = "서브 미션 무료 해제"
  },
  Activity_89730_ActivityName = {
    Text = "거울 속의 죄수"
